export const envelope = [19, 22, 43];

export default function build(api) {
  const [W, H, D] = api.size;
  const occupied = new Set();
  const baseColumns = new Map();

  function keyOf(x, y, z) {
    return `${x},${y},${z}`;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
      occupied.add(keyOf(x, y, z));
    }
  }

  function registerFooting(x, z, targetY) {
    const key = `${x},${z}`;
    if (!baseColumns.has(key) || baseColumns.get(key) > targetY) {
      baseColumns.set(key, targetY);
    }
  }

  // --- Theme block helpers ---
  function getBase(blockStr) {
    return (blockStr || "minecraft:oak_planks").split("[")[0];
  }

  function makeStairs(baseStairs, facing, half = "bottom", shape = "straight") {
    const base = getBase(baseStairs);
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function makeSlab(baseSlab, type = "bottom") {
    const base = getBase(baseSlab);
    return `${base}[type=${type}]`;
  }

  function makeLog(baseLog, axis = "y") {
    const base = getBase(baseLog);
    return `${base}[axis=${axis}]`;
  }

  function makeTrapdoor(baseTrapdoor, facing = "north", half = "bottom", open = false) {
    const base = getBase(baseTrapdoor);
    return `${base}[facing=${facing},half=${half},open=${open}]`;
  }

  function makeDoor(baseDoor, facing = "north", half = "lower", hinge = "left", open = false) {
    const base = getBase(baseDoor);
    return `${base}[facing=${facing},half=${half},hinge=${hinge},open=${open}]`;
  }

  const cx = 8; // Ship centerline in X

  // --- Hull half-width formula ---
  function getHullHalfWidth(z, y) {
    if (z < 4 || z > 38) return -1;
    let maxW;
    if (z <= 12) {
      const t = (z - 4) / 8;
      maxW = 0.5 + 3.7 * Math.sin(t * Math.PI * 0.5);
    } else if (z <= 29) {
      maxW = 4.2;
    } else {
      const t = (z - 29) / 9;
      maxW = 4.2 - 3.2 * (t * t);
    }

    if (y <= 1) return 0.5;
    if (y === 2) return Math.max(0.5, maxW - 1.2);
    if (y === 3) return Math.max(0.8, maxW - 0.7);
    if (y === 4) return Math.max(1.0, maxW - 0.2);
    return maxW;
  }

  // ==========================================
  // 1. KEEL, LOWER HULL, AND MAIN DECK
  // ==========================================

  // Keel timber along bottom
  for (let z = 4; z <= 38; z++) {
    for (let y = 1; y <= 2; y++) {
      setBlock(cx, y, z, makeLog(api.theme.wood.log, "z"));
      registerFooting(cx, z, 1);
    }
  }

  // Lower hull planking (y = 2 to 4)
  for (let z = 4; z <= 38; z++) {
    for (let y = 2; y <= 4; y++) {
      const hw = getHullHalfWidth(z, y);
      if (hw < 0) continue;
      const minX = Math.round(cx - hw);
      const maxX = Math.round(cx + hw);

      for (let x = minX; x <= maxX; x++) {
        const isOuter = (x === minX || x === maxX || y === 2);
        if (isOuter) {
          setBlock(x, y, z, api.theme.wood.stripped);
        } else {
          setBlock(x, y, z, api.theme.wood.planks);
        }
        registerFooting(x, z, y);
      }
    }
  }

  // Gold / brass sheer-strake line at y = 4 along hull edges
  for (let z = 4; z <= 38; z++) {
    const hw = getHullHalfWidth(z, 4);
    if (hw >= 1.0) {
      const minX = Math.round(cx - hw);
      const maxX = Math.round(cx + hw);
      setBlock(minX, 4, z, "minecraft:cut_copper");
      setBlock(maxX, 4, z, "minecraft:cut_copper");
    }
  }

  // Main Deck Flooring (y = 5)
  for (let z = 4; z <= 38; z++) {
    const hw = getHullHalfWidth(z, 5);
    if (hw < 0) continue;
    const minX = Math.round(cx - hw);
    const maxX = Math.round(cx + hw);

    for (let x = minX; x <= maxX; x++) {
      const isEdge = (x === minX || x === maxX);
      if (isEdge) {
        setBlock(x, 5, z, makeLog(api.theme.wood.log, "z"));
      } else {
        setBlock(x, 5, z, api.theme.wood.planks);
      }
      registerFooting(x, z, 5);
    }
  }

  // Main Deck Bulwarks / Railings (y = 6)
  for (let z = 4; z <= 38; z++) {
    const hw = getHullHalfWidth(z, 5);
    if (hw < 0) continue;
    const minX = Math.round(cx - hw);
    const maxX = Math.round(cx + hw);

    // Open forecastle deck (z=5..12) and aft fantail deck (z=34..38)
    const isForeDeck = (z >= 5 && z <= 12);
    const isAftDeck = (z >= 34 && z <= 38);
    const isMidDeckPassage = (z >= 13 && z <= 33);

    if (isForeDeck || isAftDeck) {
      setBlock(minX, 6, z, api.theme.wood.fence);
      setBlock(maxX, 6, z, api.theme.wood.fence);
    } else if (isMidDeckPassage) {
      // Outer rub rail along side decks
      if (z < 18 || z > 26) {
        setBlock(minX, 6, z, api.theme.wood.fence);
        // Starboard boarding gap at z=16
        if (z !== 16) {
          setBlock(maxX, 6, z, api.theme.wood.fence);
        }
      }
    }
  }

  // Sharp Stempost & Bowsprit
  setBlock(cx, 5, 4, makeLog(api.theme.wood.log, "y"));
  setBlock(cx, 6, 4, makeLog(api.theme.wood.log, "y"));
  setBlock(cx, 7, 4, "minecraft:cut_copper"); // Carved figurehead scrollwork

  // Bowsprit spar reaching forward to z=1
  setBlock(cx, 6, 5, api.theme.wood.stripped);
  setBlock(cx, 6, 4, api.theme.wood.stripped);
  setBlock(cx, 7, 3, api.theme.wood.stripped);
  setBlock(cx, 7, 2, api.theme.wood.stripped);
  setBlock(cx, 8, 1, api.theme.wood.stripped);
  setBlock(cx, 8, 0, makeTrapdoor(api.theme.wood.trapdoor, "north", "bottom", false));

  // Bowsprit rigging stay down to stem cutwater
  setBlock(cx, 7, 1, "minecraft:chain");
  setBlock(cx, 6, 2, "minecraft:chain");
  setBlock(cx, 5, 3, "minecraft:chain");

  // Hawseholes & Anchor chains on bow
  setBlock(cx - 2, 6, 6, "minecraft:chain");
  setBlock(cx - 2, 5, 6, "minecraft:chain");
  setBlock(cx - 2, 4, 6, "minecraft:chain");
  setBlock(cx + 2, 6, 6, "minecraft:chain");
  setBlock(cx + 2, 5, 6, "minecraft:chain");
  setBlock(cx + 2, 4, 6, "minecraft:chain");

  // Foredeck Capstan / Windlass & Mooring Bitts
  setBlock(cx, 6, 7, "minecraft:grindstone[facing=north]");
  setBlock(cx - 2, 6, 8, makeLog(api.theme.wood.log, "y"));
  setBlock(cx - 2, 7, 8, makeTrapdoor(api.theme.wood.trapdoor, "north", "top", false));
  setBlock(cx + 2, 6, 8, makeLog(api.theme.wood.log, "y"));
  setBlock(cx + 2, 7, 8, makeTrapdoor(api.theme.wood.trapdoor, "north", "top", false));

  // Stern Rudder & Rudder Post
  for (let y = 1; y <= 4; y++) {
    setBlock(cx, y, 38, makeLog(api.theme.wood.log, "y"));
    setBlock(cx, y, 39, api.theme.wood.planks);
    registerFooting(cx, 38, 1);
    registerFooting(cx, 39, 1);
  }

  // ==========================================
  // 2. PADDLE WHEEL HOUSINGS & WHEELS
  // ==========================================

  function buildPaddleBox(minBoxX, maxBoxX, outerX) {
    // Housing base and lower rim
    for (let z = 18; z <= 26; z++) {
      for (let x = minBoxX; x <= maxBoxX; x++) {
        setBlock(x, 4, z, api.theme.wood.planks);
        setBlock(x, 5, z, api.theme.wood.planks);
        registerFooting(x, z, 4);
      }
    }

    // Outer face decorative arched casing
    for (let z = 18; z <= 26; z++) {
      // Solid outer corners
      if (z === 18 || z === 26) {
        setBlock(outerX, 6, z, api.theme.wood.planks);
        setBlock(outerX, 7, z, api.theme.wood.planks);
      } else if (z === 19 || z === 25) {
        setBlock(outerX, 6, z, api.theme.wood.planks);
        setBlock(outerX, 7, z, api.theme.wood.stairs);
      } else if (z === 20 || z === 24) {
        setBlock(outerX, 6, z, "minecraft:iron_bars");
        setBlock(outerX, 7, z, api.theme.wood.planks);
      } else {
        // Center opening z=21..23 showing wheel hub & spokes
        setBlock(outerX, 6, z, "minecraft:iron_bars");
        setBlock(outerX, 7, z, "minecraft:iron_bars");
      }
    }

    // Center decorative sunburst medallion on outer paddle box
    setBlock(outerX, 7, 22, "minecraft:cut_copper");

    // Curved drum casing top (y = 6 to 9)
    for (let x = minBoxX; x <= maxBoxX; x++) {
      setBlock(x, 6, 18, makeStairs(api.theme.wood.stairs, "north", "bottom"));
      setBlock(x, 6, 26, makeStairs(api.theme.wood.stairs, "south", "bottom"));
      setBlock(x, 7, 19, makeStairs(api.theme.wood.stairs, "north", "bottom"));
      setBlock(x, 7, 25, makeStairs(api.theme.wood.stairs, "south", "bottom"));
      setBlock(x, 8, 20, makeStairs(api.theme.wood.stairs, "north", "bottom"));
      setBlock(x, 8, 24, makeStairs(api.theme.wood.stairs, "south", "bottom"));
      setBlock(x, 9, 21, makeSlab(api.theme.wood.slab, "bottom"));
      setBlock(x, 9, 22, makeSlab(api.theme.wood.slab, "bottom"));
      setBlock(x, 9, 23, makeSlab(api.theme.wood.slab, "bottom"));
    }

    // Interior Paddle Wheel (blades & axle)
    const wheelX1 = minBoxX + 1;
    const wheelX2 = maxBoxX - 1;
    for (let wx = wheelX1; wx <= wheelX2; wx++) {
      // Axle hub
      setBlock(wx, 5, 22, makeLog(api.theme.wood.log, "x"));
      // Radial paddle blades
      setBlock(wx, 3, 22, api.theme.wood.planks); // Bottom paddle in water
      setBlock(wx, 4, 20, api.theme.wood.planks);
      setBlock(wx, 4, 24, api.theme.wood.planks);
      setBlock(wx, 5, 19, api.theme.wood.planks); // Fore paddle
      setBlock(wx, 5, 25, api.theme.wood.planks); // Aft paddle
      setBlock(wx, 6, 20, api.theme.wood.planks);
      setBlock(wx, 6, 24, api.theme.wood.planks);
      setBlock(wx, 7, 22, api.theme.wood.planks); // Top paddle
      // Wheel spokes
      setBlock(wx, 4, 22, "minecraft:iron_bars");
      setBlock(wx, 6, 22, "minecraft:iron_bars");
      setBlock(wx, 5, 21, "minecraft:iron_bars");
      setBlock(wx, 5, 23, "minecraft:iron_bars");
    }
  }

  // Port paddle box (x = 1 to 4)
  buildPaddleBox(1, 4, 1);
  // Starboard paddle box (x = 12 to 15)
  buildPaddleBox(12, 15, 15);

  // ==========================================
  // 3. CABINS & SUPERSTRUCTURE (MAIN DECK)
  // ==========================================

  // Forward Cabin (Lounge / Quarters): z = 13 to 18, x = 5 to 11
  for (let z = 13; z <= 18; z++) {
    for (let x = 5; x <= 11; x++) {
      const isCorner = (x === 5 || x === 11) && (z === 13 || z === 18);
      const isWallX = (x === 5 || x === 11);
      const isWallZ = (z === 13 || z === 18);

      if (isWallX || isWallZ) {
        if (isCorner) {
          setBlock(x, 6, z, makeLog(api.theme.wood.log, "y"));
          setBlock(x, 7, z, makeLog(api.theme.wood.log, "y"));
        } else if (z === 13 && x === cx) {
          // Forward entrance door
          setBlock(x, 6, z, makeDoor(api.theme.wood.door, "north", "lower"));
          setBlock(x, 7, z, makeDoor(api.theme.wood.door, "north", "upper"));
        } else if (x === 11 && z === 16) {
          // Starboard entrance door from boarding gangway
          setBlock(x, 6, z, makeDoor(api.theme.wood.door, "east", "lower"));
          setBlock(x, 7, z, makeDoor(api.theme.wood.door, "east", "upper"));
        } else if (z === 18 && x === cx) {
          // Passageway aft door
          setBlock(x, 6, z, makeDoor(api.theme.wood.door, "south", "lower"));
          setBlock(x, 7, z, makeDoor(api.theme.wood.door, "south", "upper"));
        } else {
          // Walls with Victorian passenger windows
          setBlock(x, 6, z, api.theme.wood.planks);
          if (z === 13 || z === 18 || (z % 2 === 0)) {
            setBlock(x, 7, z, "minecraft:glass_pane");
          } else {
            setBlock(x, 7, z, api.theme.wood.planks);
          }
        }
      }
    }
  }

  // Midships Engine Room Casing: z = 19 to 23, x = 6 to 10
  for (let z = 19; z <= 23; z++) {
    for (let x = 6; x <= 10; x++) {
      if (x === 6 || x === 10 || z === 19 || z === 23) {
        setBlock(x, 6, z, api.theme.wood.planks);
        setBlock(x, 7, z, api.theme.wood.planks);
      }
    }
  }

  // Companionway stairs from main deck up to upper promenade deck
  setBlock(5, 6, 19, makeStairs(api.theme.wood.stairs, "south", "bottom"));
  setBlock(5, 7, 20, makeStairs(api.theme.wood.stairs, "south", "bottom"));
  setBlock(11, 6, 19, makeStairs(api.theme.wood.stairs, "south", "bottom"));
  setBlock(11, 7, 20, makeStairs(api.theme.wood.stairs, "south", "bottom"));

  // Aft Grand Passenger Saloon: z = 24 to 34, x = 5 to 11
  for (let z = 24; z <= 34; z++) {
    const hw = (z <= 30) ? 3.0 : (z <= 32 ? 2.5 : 2.0);
    const minX = Math.round(cx - hw);
    const maxX = Math.round(cx + hw);

    for (let x = minX; x <= maxX; x++) {
      const isWall = (x === minX || x === maxX || z === 24 || z === 34);
      if (isWall) {
        if (z === 24 && x === cx) {
          // Entrance into grand saloon
          setBlock(x, 6, z, makeDoor(api.theme.wood.door, "north", "lower"));
          setBlock(x, 7, z, makeDoor(api.theme.wood.door, "north", "upper"));
        } else if (z === 34 && x === cx) {
          // Aft door out to fantail
          setBlock(x, 6, z, makeDoor(api.theme.wood.door, "south", "lower"));
          setBlock(x, 7, z, makeDoor(api.theme.wood.door, "south", "upper"));
        } else {
          setBlock(x, 6, z, api.theme.wood.planks);
          // Alternating grand picture windows
          if ((x + z) % 2 === 0) {
            setBlock(x, 7, z, "minecraft:glass_pane");
          } else {
            setBlock(x, 7, z, api.theme.wood.planks);
          }
        }
      }
    }
  }

  // ==========================================
  // 4. HURRICANE / UPPER PROMENADE DECK (y = 8)
  // ==========================================

  for (let z = 12; z <= 36; z++) {
    let hw;
    if (z <= 12) hw = 3.0;
    else if (z <= 28) hw = 3.5;
    else if (z <= 32) hw = 3.0;
    else hw = 2.0;

    const minX = Math.round(cx - hw);
    const maxX = Math.round(cx + hw);

    for (let x = minX; x <= maxX; x++) {
      setBlock(x, 8, z, api.theme.wood.planks);
      registerFooting(x, z, 8);

      // Deck Railing at y = 9
      const isEdge = (x === minX || x === maxX || z === 12 || z === 36);
      if (isEdge) {
        setBlock(x, 9, z, api.theme.wood.fence);
      }
    }
  }

  // Promenade deck passenger benches & skylights
  setBlock(cx - 2, 9, 26, makeStairs(api.theme.wood.stairs, "east", "bottom"));
  setBlock(cx + 2, 9, 26, makeStairs(api.theme.wood.stairs, "west", "bottom"));
  setBlock(cx - 2, 9, 31, makeStairs(api.theme.wood.stairs, "east", "bottom"));
  setBlock(cx + 2, 9, 31, makeStairs(api.theme.wood.stairs, "west", "bottom"));

  // Saloon Glass Skylight atop upper deck
  for (let z = 27; z <= 29; z++) {
    setBlock(cx, 8, z, "minecraft:glass");
    setBlock(cx, 9, z, makeTrapdoor(api.theme.wood.trapdoor, "north", "bottom", false));
  }

  // Port & Starboard Lifeboats on iron davits
  function buildLifeboat(bx, z1, z2) {
    setBlock(bx, 9, z1, "minecraft:iron_bars");
    setBlock(bx, 10, z1, "minecraft:iron_bars");
    setBlock(bx, 9, z2, "minecraft:iron_bars");
    setBlock(bx, 10, z2, "minecraft:iron_bars");

    for (let z = z1; z <= z2; z++) {
      if (z === z1) {
        setBlock(bx, 9, z, makeStairs(api.theme.wood.stairs, "north", "bottom"));
      } else if (z === z2) {
        setBlock(bx, 9, z, makeStairs(api.theme.wood.stairs, "south", "bottom"));
      } else {
        setBlock(bx, 9, z, makeSlab(api.theme.wood.slab, "bottom"));
      }
    }
  }
  buildLifeboat(cx - 4, 28, 31);
  buildLifeboat(cx + 4, 28, 31);

  // ==========================================
  // 5. PILOT HOUSE (WHEELHOUSE)
  // ==========================================

  // Pilot house floor at y = 9, walls at y = 10..11, roof at y = 12
  for (let z = 13; z <= 17; z++) {
    for (let x = cx - 2; x <= cx + 2; x++) {
      // Floor
      setBlock(x, 9, z, api.theme.wood.planks);

      const isWall = (x === cx - 2 || x === cx + 2 || z === 13 || z === 17);
      if (isWall) {
        if (z === 17 && x === cx) {
          // Aft door into wheelhouse
          setBlock(x, 10, z, makeDoor(api.theme.wood.door, "south", "lower"));
          setBlock(x, 11, z, makeDoor(api.theme.wood.door, "south", "upper"));
        } else {
          // Lower wainscoting
          setBlock(x, 10, z, api.theme.wood.planks);
          // Panoramic observation glass
          setBlock(x, 11, z, "minecraft:glass_pane");
        }
      }
    }
  }

  // Pilot house curved overhanging roof at y = 12
  for (let z = 12; z <= 18; z++) {
    for (let x = cx - 3; x <= cx + 3; x++) {
      const isEdgeX = (x === cx - 3 || x === cx + 3);
      const isEdgeZ = (z === 12 || z === 18);

      if (isEdgeZ && isEdgeX) {
        setBlock(x, 12, z, makeSlab(api.theme.wood.slab, "top"));
      } else if (z === 12) {
        setBlock(x, 12, z, makeStairs(api.theme.wood.stairs, "north", "bottom"));
      } else if (z === 18) {
        setBlock(x, 12, z, makeStairs(api.theme.wood.stairs, "south", "bottom"));
      } else if (x === cx - 3) {
        setBlock(x, 12, z, makeStairs(api.theme.wood.stairs, "west", "bottom"));
      } else if (x === cx + 3) {
        setBlock(x, 12, z, makeStairs(api.theme.wood.stairs, "east", "bottom"));
      } else {
        setBlock(x, 12, z, makeSlab(api.theme.wood.slab, "top"));
      }
    }
  }

  // Wheelhouse Roof Instruments (Searchlight, Bell, Binnacle)
  setBlock(cx, 13, 13, "minecraft:sea_lantern");
  setBlock(cx, 14, 13, makeSlab(api.theme.wood.slab, "bottom"));
  setBlock(cx, 13, 14, "minecraft:bell");
  setBlock(cx, 13, 16, api.theme.wood.fence);

  // ==========================================
  // 6. WALKING BEAM STEAM ENGINE
  // ==========================================

  // Engine triangular A-frame support structure (y = 9 to 11)
  for (let y = 9; y <= 11; y++) {
    setBlock(cx - 1, y, 22, makeLog(api.theme.wood.log, "y"));
    setBlock(cx + 1, y, 22, makeLog(api.theme.wood.log, "y"));
    setBlock(cx - 1, y, 23, makeLog(api.theme.wood.log, "y"));
    setBlock(cx + 1, y, 23, makeLog(api.theme.wood.log, "y"));
  }

  // Central rocking pivot bearing
  setBlock(cx - 1, 12, 22, "minecraft:smooth_stone_slab[type=bottom]");
  setBlock(cx, 12, 22, "minecraft:polished_blackstone");
  setBlock(cx + 1, 12, 22, "minecraft:smooth_stone_slab[type=bottom]");
  setBlock(cx, 12, 23, "minecraft:polished_blackstone");

  // Iconic Diamond Walking Beam (tilted lever arm)
  // Forward upward tip at (cx, 14, 20)
  setBlock(cx, 14, 20, "minecraft:smooth_stone_slab[type=bottom]");
  setBlock(cx, 13, 21, "minecraft:iron_bars");
  setBlock(cx, 14, 22, "minecraft:smooth_stone_slab[type=top]"); // Diamond top crest
  setBlock(cx, 13, 22, "minecraft:iron_bars");
  setBlock(cx, 11, 23, "minecraft:iron_bars");
  setBlock(cx, 10, 23, "minecraft:smooth_stone_slab[type=bottom]"); // Diamond bottom keel
  setBlock(cx, 11, 24, "minecraft:iron_bars");
  // Aft downward tip at (cx, 10, 25)
  setBlock(cx, 10, 25, "minecraft:smooth_stone_slab[type=bottom]");

  // Forward Piston Connecting Rod dropping to cylinder
  setBlock(cx, 13, 20, "minecraft:chain");
  setBlock(cx, 12, 20, "minecraft:chain");
  setBlock(cx, 11, 20, "minecraft:chain");
  setBlock(cx, 10, 20, "minecraft:chain");
  setBlock(cx, 9, 20, "minecraft:polished_basalt[axis=y]"); // Steam Cylinder
  setBlock(cx, 8, 20, "minecraft:polished_basalt[axis=y]");

  // Aft Pitman Rod dropping to paddle wheel crank
  setBlock(cx, 9, 25, "minecraft:iron_bars");
  setBlock(cx, 8, 25, "minecraft:iron_bars");
  setBlock(cx, 7, 25, "minecraft:iron_bars");

  // ==========================================
  // 7. TALL SMOKESTACK (FUNNEL)
  // ==========================================

  // Funnel base collar at y = 8
  setBlock(cx, 8, 18, "minecraft:polished_blackstone");
  setBlock(cx, 8, 19, "minecraft:polished_blackstone");

  // Raked Smokestack column from y = 9 to 16
  for (let y = 9; y <= 16; y++) {
    if (y === 14) {
      // Victorian brass band
      setBlock(cx, y, 18, "minecraft:cut_copper");
      setBlock(cx, y, 19, "minecraft:cut_copper");
    } else if (y === 16) {
      // Flared flanged cowl top
      setBlock(cx, y, 18, makeStairs("minecraft:polished_blackstone_stairs", "north", "bottom"));
      setBlock(cx, y, 19, makeStairs("minecraft:polished_blackstone_stairs", "south", "bottom"));
    } else {
      setBlock(cx, y, 18, "minecraft:polished_blackstone");
      setBlock(cx, y, 19, "minecraft:polished_blackstone");
    }
  }

  // Steam & Smoke Particles at top of stack
  setBlock(cx, 16, 18, "minecraft:campfire[lit=true,signal_fire=true]");
  setBlock(cx, 17, 18, "minecraft:iron_trapdoor[half=top]");
  setBlock(cx, 17, 19, "minecraft:white_stained_glass");
  setBlock(cx, 18, 19, "minecraft:white_stained_glass");

  // Funnel Guy Wires (Chains) anchored to deck
  setBlock(cx - 1, 14, 18, "minecraft:chain");
  setBlock(cx - 2, 13, 17, "minecraft:chain");
  setBlock(cx - 3, 11, 16, "minecraft:chain");
  setBlock(cx - 3, 9, 16, "minecraft:chain");

  setBlock(cx + 1, 14, 18, "minecraft:chain");
  setBlock(cx + 2, 13, 17, "minecraft:chain");
  setBlock(cx + 3, 11, 16, "minecraft:chain");
  setBlock(cx + 3, 9, 16, "minecraft:chain");

  // ==========================================
  // 8. MASTS, SPARS, RIGGING & PENNANTS
  // ==========================================

  // Foremast (z = 9): base at deck y = 5 up to y = 19
  for (let y = 5; y <= 12; y++) {
    setBlock(cx, y, 9, makeLog(api.theme.wood.log, "y"));
  }
  for (let y = 13; y <= 19; y++) {
    setBlock(cx, y, 9, api.theme.wood.fence);
  }

  // Foremast Cross Yardarm at y = 15
  for (let x = cx - 2; x <= cx + 2; x++) {
    setBlock(x, 15, 9, api.theme.wood.fence);
  }

  // Foremast Shrouds & Forestay
  setBlock(cx - 2, 14, 9, "minecraft:chain");
  setBlock(cx - 3, 11, 9, "minecraft:chain");
  setBlock(cx - 3, 7, 9, "minecraft:chain");

  setBlock(cx + 2, 14, 9, "minecraft:chain");
  setBlock(cx + 3, 11, 9, "minecraft:chain");
  setBlock(cx + 3, 7, 9, "minecraft:chain");

  // Forestay to bowsprit tip
  setBlock(cx, 16, 7, "minecraft:chain");
  setBlock(cx, 13, 5, "minecraft:chain");
  setBlock(cx, 10, 3, "minecraft:chain");

  // Victorian Resort Pennant atop foremast
  setBlock(cx, 19, 10, "minecraft:red_wool");
  setBlock(cx, 19, 11, "minecraft:white_wool");

  // Mainmast (z = 33): base at deck y = 8 up to y = 18
  for (let y = 8; y <= 11; y++) {
    setBlock(cx, y, 33, makeLog(api.theme.wood.log, "y"));
  }
  for (let y = 12; y <= 18; y++) {
    setBlock(cx, y, 33, api.theme.wood.fence);
  }

  // Gaff spar angled back toward stern
  setBlock(cx, 14, 34, api.theme.wood.fence);
  setBlock(cx, 15, 35, api.theme.wood.fence);
  setBlock(cx, 16, 36, api.theme.wood.fence);

  // Ensign flag at gaff peak
  setBlock(cx, 15, 36, "minecraft:red_wool");
  setBlock(cx, 14, 36, "minecraft:white_wool");

  // ==========================================
  // 9. PLEASURE PIER & MOORING CONNECTIONS
  // ==========================================

  // Starboard Pier Deck (x = 16 to 18, z = 12 to 36, y = 5)
  for (let z = 12; z <= 36; z++) {
    for (let x = 16; x <= 18; x++) {
      if (x === 16 || x === 18) {
        setBlock(x, 5, z, makeLog(api.theme.wood.log, "z"));
      } else {
        setBlock(x, 5, z, api.theme.wood.planks);
      }
      registerFooting(x, z, 5);

      // East safety fence along pier
      if (x === 18) {
        setBlock(x, 6, z, api.theme.wood.fence);
      }
    }
  }

  // Pier Pilings & Mooring Bollards at regular bays
  const pilingZ = [12, 16, 20, 24, 28, 32, 36];
  for (const pz of pilingZ) {
    for (const px of [16, 18]) {
      // Piling bollard head above pier
      setBlock(px, 6, pz, makeLog(api.theme.wood.log, "y"));
      setBlock(px, 7, pz, makeTrapdoor(api.theme.wood.trapdoor, "north", "top", false));
    }
  }

  // Gas Lanterns on Pier Posts
  setBlock(18, 7, 16, api.theme.wood.fence);
  setBlock(18, 8, 16, "minecraft:lantern[hanging=false]");
  setBlock(18, 7, 32, api.theme.wood.fence);
  setBlock(18, 8, 32, "minecraft:lantern[hanging=false]");

  // Boarding Gangway: spans x = 12 (ship) to x = 16 (pier) at z = 16
  for (let x = 12; x <= 16; x++) {
    setBlock(x, 5, 16, api.theme.wood.planks);
    registerFooting(x, 16, 5);
    // Rope handrails
    if (x > 12 && x < 16) {
      setBlock(x, 6, 15, api.theme.wood.fence);
      setBlock(x, 6, 17, api.theme.wood.fence);
    }
  }

  // Mooring Lines (Chains / Ropes securing ship to pier)
  // Forward spring line
  setBlock(12, 6, 10, makeLog(api.theme.wood.log, "y"));
  setBlock(13, 6, 11, "minecraft:chain");
  setBlock(14, 6, 12, "minecraft:chain");
  setBlock(15, 6, 13, "minecraft:chain");
  setBlock(16, 6, 14, makeLog(api.theme.wood.log, "y"));

  // Midships breast line
  setBlock(12, 6, 27, makeLog(api.theme.wood.log, "y"));
  setBlock(13, 6, 26, "minecraft:chain");
  setBlock(14, 6, 26, "minecraft:chain");
  setBlock(15, 6, 26, "minecraft:chain");

  // Aft mooring line
  setBlock(11, 6, 35, makeLog(api.theme.wood.log, "y"));
  setBlock(12, 6, 35, "minecraft:chain");
  setBlock(13, 6, 35, "minecraft:chain");
  setBlock(14, 6, 36, "minecraft:chain");
  setBlock(15, 6, 36, "minecraft:chain");

  // ==========================================
  // 10. GROUND CONFORMITY & FOOTINGS
  // ==========================================

  // Follow terrain height at every occupied footprint column
  for (const [colKey, targetY] of baseColumns.entries()) {
    const [sx, sz] = colKey.split(",").map(Number);
    const groundY = Math.round(api.heightAt(sx, sz));

    // Fill downwards to ground or up to rising ground
    const startY = Math.max(0, Math.min(targetY, groundY));
    const endY = Math.max(targetY, Math.min(H - 1, groundY));

    for (let y = startY; y <= endY; y++) {
      if (!occupied.has(keyOf(sx, y, sz))) {
        setBlock(sx, y, sz, makeLog(api.theme.wood.log, "y"));
      }
    }
  }

  // ==========================================
  // 11. RETURN STRUCTURE METADATA
  // ==========================================

  return {
    name: "Paddle Steamer",
    seatY: 0,
    anchors: {
      front: [cx, 8, 0],
      door: [17, 5, 12],
      pier: [17, 5, 36]
    },
    interiors: [
      {
        min: [5, 6, 25],
        max: [11, 8, 33],
        kind: "hall"
      },
      {
        min: [5, 6, 14],
        max: [11, 8, 18],
        kind: "quarters"
      },
      {
        min: [6, 10, 14],
        max: [10, 12, 17],
        kind: "bridge"
      }
    ]
  };
}

victorian_bandstand.source:
export const envelope = [15, 17, 15];

export default function build(api) {
  const { size, theme } = api;
  const cx = 7;
  const cz = 7;
  const seatY = 3;

  // Palette from theme with safe vanilla fallbacks
  const stonePrimary = theme?.stone?.primary || "minecraft:smooth_stone";
  const stonePlinth = theme?.ground?.plinth || theme?.stone?.primary || "minecraft:smooth_stone";
  const stoneKerb = theme?.ground?.kerb || theme?.stone?.accent || "minecraft:polished_andesite";
  const stoneSlab = theme?.ground?.slab || theme?.stone?.slab || "minecraft:smooth_stone_slab[type=bottom]";
  const stoneFoundation = theme?.ground?.revetment || theme?.stone?.primary || "minecraft:cobblestone";

  const woodPlanks = theme?.wood?.planks || "minecraft:spruce_planks";
  const woodStripped = theme?.wood?.stripped || "minecraft:stripped_spruce_log[axis=y]";
  const woodSlabTop = theme?.wood?.slab ? `${theme.wood.slab.split("[")[0]}[type=top]` : "minecraft:spruce_slab[type=top]";

  const roofSolid = theme?.roof?.solid || "minecraft:oxidized_copper";
  const roofSlabBottom = theme?.roof?.slab ? `${theme.roof.slab.split("[")[0]}[type=bottom]` : "minecraft:oxidized_cut_copper_slab[type=bottom]";

  // Victorian cast-iron, copper, and brass appointments
  const castIronPillarBase = "minecraft:polished_blackstone";
  const castIronWall = "minecraft:nether_brick_wall";
  const castIronFence = "minecraft:nether_brick_fence";
  const ironBars = "minecraft:iron_bars";
  const weatheredCutCopper = "minecraft:weathered_cut_copper";
  const oxidizedCutCopper = "minecraft:oxidized_cut_copper";

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  function isInsideOctagon(x, z) {
    const dx = Math.abs(x - cx);
    const dz = Math.abs(z - cz);
    return Math.max(dx, dz) <= 5 && (dx + dz) <= 7;
  }

  function isOctagonBoundary(x, z) {
    if (!isInsideOctagon(x, z)) return false;
    const neighbors = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (const [nx, nz] of neighbors) {
      if (!isInsideOctagon(x + nx, z + nz)) return true;
    }
    return false;
  }

  function getStairsFacing(dx, dz) {
    if (dz < 0 && Math.abs(dz) >= Math.abs(dx)) return "north";
    if (dz > 0 && Math.abs(dz) >= Math.abs(dx)) return "south";
    if (dx < 0 && Math.abs(dx) >= Math.abs(dz)) return "west";
    return "east";
  }

  // 1. FOOTPRINT & GROUND CONFORMITY SKIRT
  // Build foundation down to terrain height for every occupied column
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      let isFootprint = isInsideOctagon(x, z);

      // Include entrance steps & pedestals
      if (z === 1 && x >= 5 && x <= 9) isFootprint = true;
      if (z === 0 && x >= 5 && x <= 9) isFootprint = true;

      if (!isFootprint) continue;

      const groundRel = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(seatY, seatY + groundRel));

      // Build foundation from ground up to seat plane
      for (let y = groundY; y <= seatY; y++) {
        const mat = y === groundY && groundY < seatY ? stoneFoundation : stonePlinth;
        setBlock(x, y, z, mat);
      }
    }
  }

  // 2. PODIUM DECK (Y = 4)
  // Victorian decorative concentric wood deck with polished stone kerb
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (!isInsideOctagon(x, z)) continue;

      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      const onBoundary = isOctagonBoundary(x, z);

      if (onBoundary) {
        setBlock(x, 4, z, stoneKerb);
      } else if (dist < 1.0) {
        // Conductor's central podium base
        setBlock(x, 4, z, "minecraft:polished_blackstone_slab[type=top]");
      } else if (dist < 2.5) {
        setBlock(x, 4, woodPlanks, z);
      } else if (dist < 4.2) {
        // Alternating dark oak & spruce concert parquet
        const parquet = (x + z) % 2 === 0 ? "minecraft:dark_oak_planks" : woodPlanks;
        setBlock(x, 4, z, parquet);
      } else {
        setBlock(x, 4, z, woodStripped);
      }
    }
  }

  // 3. NORTH ENTRANCE STAIRCASE & FLANKING PEDESTALS
  // Step course 1 (z = 1)
  setBlock(6, 3, 1, "minecraft:stone_brick_stairs[facing=south,half=bottom,shape=straight]");
  setBlock(7, 3, 1, "minecraft:stone_brick_stairs[facing=south,half=bottom,shape=straight]");
  setBlock(8, 3, 1, "minecraft:stone_brick_stairs[facing=south,half=bottom,shape=straight]");

  // Step course 2 (z = 0)
  setBlock(6, 2, 0, "minecraft:stone_brick_stairs[facing=south,half=bottom,shape=straight]");
  setBlock(7, 2, 0, "minecraft:stone_brick_stairs[facing=south,half=bottom,shape=straight]");
  setBlock(8, 2, 0, "minecraft:stone_brick_stairs[facing=south,half=bottom,shape=straight]");

  // Flanking stone pedestal posts with glowing seaside lanterns
  setBlock(5, 3, 1, stoneKerb);
  setBlock(5, 4, 1, stoneSlab);
  setBlock(5, 5, 1, "minecraft:lantern[hanging=false]");

  setBlock(9, 3, 1, stoneKerb);
  setBlock(9, 4, 1, stoneSlab);
  setBlock(9, 5, 1, "minecraft:lantern[hanging=false]");

  setBlock(5, 2, 0, stoneKerb);
  setBlock(9, 2, 0, stoneKerb);

  // 4. CAST-IRON PILLARS, BALUSTRADE, & SPANDREL BRACKETS
  const pillars = [
    [5, 2], [9, 2],
    [12, 5], [12, 9],
    [9, 12], [5, 12],
    [2, 9], [2, 5]
  ];

  // Erect the 8 cast-iron pillars
  for (const [px, pz] of pillars) {
    setBlock(px, 4, pz, castIronPillarBase);
    for (let y = 5; y <= 8; y++) {
      setBlock(px, y, pz, castIronWall);
    }
  }

  // Iron balustrade railings at Y = 5 & Filigree brackets at Y = 8
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (!isOctagonBoundary(x, z)) continue;

      const isPillar = pillars.some(([px, pz]) => px === x && pz === z);
      if (isPillar) continue;

      // Leave North entrance open
      const isNorthEntrance = z === 2 && x >= 6 && x <= 8;
      if (!isNorthEntrance) {
        setBlock(x, 5, z, ironBars);
      }

      // Spandrel arch brackets at Y = 8
      const isCardinalCenter = (z === 2 && x === 7) || (x === 12 && z === 7) ||
                              (z === 12 && x === 7) || (x === 2 && z === 7);

      if (isCardinalCenter) {
        setBlock(x, 8, z, ironBars);
        setBlock(x, 7, z, "minecraft:lantern[hanging=true]");
      } else {
        setBlock(x, 8, z, castIronFence);
      }
    }
  }

  // 5. CEILING, ARCHITRAVE, & CENTRAL CHANDELIER (Y = 9)
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (!isInsideOctagon(x, z)) continue;

      const onBoundary = isOctagonBoundary(x, z);
      const dx = x - cx;
      const dz = z - cz;

      if (onBoundary) {
        setBlock(x, 9, z, weatheredCutCopper);
      } else if (Math.abs(dx) === Math.abs(dz) || dx === 0 || dz === 0) {
        // Radial timber coffering ribs
        setBlock(x, 9, z, woodPlanks);
      } else {
        setBlock(x, 9, z, woodSlabTop);
      }
    }
  }

  // Victorian gas chandelier fixture
  setBlock(cx, 9, cz, "minecraft:gold_block");
  setBlock(cx, 8, cz, "minecraft:chain[axis=y]");
  setBlock(cx, 7, cz, "minecraft:ochre_froglight");
  setBlock(cx, 6, cz, "minecraft:lantern[hanging=true]");

  // 6. TIERED COPPER PAVILION ROOF (Y = 9 to Y = 16)
  // Tier 1: Flared Eave Overhang at Y = 9
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      const inEaves = Math.max(dx, dz) <= 6 && (dx + dz) <= 8;
      if (inEaves && !isInsideOctagon(x, z)) {
        setBlock(x, 9, z, roofSlabBottom);
      }
    }
  }

  // Tier 1: Lower Swept Roof Slope at Y = 10
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (!isInsideOctagon(x, z)) continue;

      const dx = x - cx;
      const dz = z - cz;
      const onBoundary = isOctagonBoundary(x, z);

      if (onBoundary) {
        const facing = getStairsFacing(dx, dz);
        setBlock(x, 10, z, `minecraft:oxidized_cut_copper_stairs[facing=${facing},half=bottom,shape=straight]`);
      } else {
        setBlock(x, 10, z, roofSolid);
      }
    }
  }

  // Tier 2: Mid Swept Mansard Slope at Y = 11
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const adx = Math.abs(dx);
      const adz = Math.abs(dz);
      const inMidOctagon = Math.max(adx, adz) <= 4 && (adx + adz) <= 5;

      if (!inMidOctagon) continue;

      const onMidBoundary = Math.max(adx, adz) === 4 || (adx + adz) === 5;
      if (onMidBoundary) {
        const facing = getStairsFacing(dx, dz);
        setBlock(x, 11, z, `minecraft:oxidized_cut_copper_stairs[facing=${facing},half=bottom,shape=straight]`);
      } else {
        setBlock(x, 11, z, roofSolid);
      }
    }
  }

  // Tier 3: Clerestory Ventilation Turret at Y = 12
  for (let x = cx - 2; x <= cx + 2; x++) {
    for (let z = cz - 2; z <= cz + 2; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx + dz > 3) continue;

      const isCorner = dx === 1 && dz === 1;
      const isLouver = (dx === 2 && dz === 0) || (dx === 0 && dz === 2);

      if (isCorner) {
        setBlock(x, 12, z, oxidizedCutCopper);
      } else if (isLouver) {
        setBlock(x, 12, z, ironBars);
      } else {
        setBlock(x, 12, z, roofSolid);
      }
    }
  }

  // Tier 4: Cupola Ogee Dome Cap at Y = 13
  setBlock(cx, 13, cz, roofSolid);
  setBlock(cx, 13, cz - 1, "minecraft:weathered_cut_copper_stairs[facing=north,half=bottom,shape=straight]");
  setBlock(cx, 13, cz + 1, "minecraft:weathered_cut_copper_stairs[facing=south,half=bottom,shape=straight]");
  setBlock(cx - 1, 13, cz, "minecraft:weathered_cut_copper_stairs[facing=west,half=bottom,shape=straight]");
  setBlock(cx + 1, 13, cz, "minecraft:weathered_cut_copper_stairs[facing=east,half=bottom,shape=straight]");
  setBlock(cx - 1, 13, cz - 1, roofSlabBottom);
  setBlock(cx + 1, 13, cz - 1, roofSlabBottom);
  setBlock(cx - 1, 13, cz + 1, roofSlabBottom);
  setBlock(cx + 1, 13, cz + 1, roofSlabBottom);

  // Tier 5: Spire & Directional Weathervane (Y = 14 to 16)
  setBlock(cx, 14, cz, "minecraft:cut_copper_slab[type=bottom]");
  setBlock(cx, 15, cz, "minecraft:lightning_rod[facing=up]");
  setBlock(cx, 15, cz - 1, ironBars); // North indicator
  setBlock(cx, 15, cz + 1, ironBars); // South indicator
  setBlock(cx - 1, 15, cz, ironBars); // West indicator
  setBlock(cx + 1, 15, cz, ironBars); // East indicator
  setBlock(cx, 16, cz, "minecraft:lightning_rod[facing=up]"); // Vane finial

  // 7. ORCHESTRAL APPOINTMENTS (Brass stands, Conductor Rostrum, Musicians' Chairs)
  // Conductor's music stand with open score
  setBlock(cx, 5, cz - 1, "minecraft:lectern[facing=south,has_book=true]");

  // Brass music stands (lightning rods)
  setBlock(5, 5, 6, "minecraft:lightning_rod[facing=up]");
  setBlock(9, 5, 6, "minecraft:lightning_rod[facing=up]");
  setBlock(5, 5, 8, "minecraft:lightning_rod[facing=up]");
  setBlock(9, 5, 8, "minecraft:lightning_rod[facing=up]");

  // Musicians' dark oak chairs facing the conductor
  setBlock(4, 5, 6, "minecraft:dark_oak_stairs[facing=east,half=bottom,shape=straight]");
  setBlock(4, 5, 8, "minecraft:dark_oak_stairs[facing=east,half=bottom,shape=straight]");
  setBlock(10, 5, 6, "minecraft:dark_oak_stairs[facing=west,half=bottom,shape=straight]");
  setBlock(10, 5, 8, "minecraft:dark_oak_stairs[facing=west,half=bottom,shape=straight]");
  setBlock(6, 5, 9, "minecraft:dark_oak_stairs[facing=north,half=bottom,shape=straight]");
  setBlock(8, 5, 9, "minecraft:dark_oak_stairs[facing=north,half=bottom,shape=straight]");

  // Promenade concert grand bass drum
  setBlock(cx, 5, cz + 2, "minecraft:note_block");

  return {
    name: "Victorian Bandstand",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
      door: [cx, seatY + 1, 2]
    }
  };
}

