export const envelope = [15, 30, 15];

export default function build(api) {
  const size = api.size;
  const seatY = 4;

  // Safe block placement
  function setSafe(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  // Terrain ground height node-local Y
  function groundY(x, z) {
    const localH = api.heightAt(Math.max(0, Math.min(size[0] - 1, x)), Math.max(0, Math.min(size[2] - 1, z)));
    return seatY + localH;
  }

  // 6-Connected column down to ground
  function fillColumnToGround(x, z, topY, block) {
    const g = groundY(x, z);
    const minY = Math.max(0, Math.min(topY, g));
    const maxY = Math.min(size[1] - 1, Math.max(topY, g));
    for (let y = minY; y <= maxY; y++) {
      setSafe(x, y, z, block);
    }
  }

  // 6-Connected line rasterizer (strictly face-adjacent steps)
  function draw6ConnectedLine(x0, y0, z0, x1, y1, z1, block) {
    let cx = Math.round(x0);
    let cy = Math.round(y0);
    let cz = Math.round(z0);
    const tx = Math.round(x1);
    const ty = Math.round(y1);
    const tz = Math.round(z1);

    setSafe(cx, cy, cz, block);
    while (cx !== tx || cy !== ty || cz !== tz) {
      const dx = tx - cx;
      const dy = ty - cy;
      const dz = tz - cz;
      const ax = Math.abs(dx);
      const ay = Math.abs(dy);
      const az = Math.abs(dz);

      if (ax >= ay && ax >= az) {
        cx += Math.sign(dx);
      } else if (ay >= ax && ay >= az) {
        cy += Math.sign(dy);
      } else {
        cz += Math.sign(dz);
      }
      setSafe(cx, cy, cz, block);
    }
  }

  // Safe theme material getters
  const woodPlanks = (api.theme.wood && api.theme.wood.planks) || "minecraft:oak_planks";
  const woodLog = (api.theme.wood && api.theme.wood.log) || "minecraft:oak_log";
  const woodStripped = (api.theme.wood && api.theme.wood.stripped) || "minecraft:stripped_oak_log";
  const woodFence = (api.theme.wood && api.theme.wood.fence) || "minecraft:oak_fence";
  const woodSlab = (api.theme.wood && api.theme.wood.slab) || "minecraft:oak_slab";
  const woodStairs = (api.theme.wood && api.theme.wood.stairs) || "minecraft:oak_stairs";
  const stonePlinth = (api.theme.ground && api.theme.ground.plinth) || "minecraft:stone_bricks";
  const stonePavement = (api.theme.ground && api.theme.ground.pavement) || "minecraft:cobblestone";

  // Variation presets for the 4 plugin instances
  const styleIdx = api.instance.index % 4;

  const styles = [
    {
      name: "The Royal Victoria",
      primary: "minecraft:red_wool",
      secondary: "minecraft:yellow_wool",
      accent: "minecraft:white_wool",
      trim: "minecraft:gold_block",
      sandbag: "minecraft:yellow_terracotta",
      basketElev: 2,
      envH: 14,
      pattern: 0 // Vertical gore stripes with gold equator
    },
    {
      name: "The Zephyr of the Solent",
      primary: "minecraft:blue_wool",
      secondary: "minecraft:white_wool",
      accent: "minecraft:cyan_wool",
      trim: "minecraft:lapis_block",
      sandbag: "minecraft:yellow_terracotta",
      basketElev: 4,
      envH: 13,
      pattern: 1 // Nautical spiral twist
    },
    {
      name: "The Sovereign Empress",
      primary: "minecraft:green_wool",
      secondary: "minecraft:orange_wool",
      accent: "minecraft:yellow_wool",
      trim: "minecraft:copper_block",
      sandbag: "minecraft:yellow_terracotta",
      basketElev: 3,
      envH: 14,
      pattern: 2 // Harlequin diamond
    },
    {
      name: "The Celestial Queen",
      primary: "minecraft:purple_wool",
      secondary: "minecraft:magenta_wool",
      accent: "minecraft:pink_wool",
      trim: "minecraft:white_wool",
      sandbag: "minecraft:yellow_terracotta",
      basketElev: 3,
      envH: 14,
      pattern: 3 // Victorian horizontal tiers and scallops
    }
  ];

  const current = styles[styleIdx];
  const cx = 7;
  const cz = 7;

  const basketY = seatY + current.basketElev;
  const burnerY = basketY + 3;
  const envBaseY = basketY + 4;
  const envH = current.envH;
  const envTopY = envBaseY + envH - 1;
  const maxRadius = 5.25;

  // Teardrop profile formula for the balloon envelope
  function getRadiusAtNormY(t) {
    if (t < 0 || t > 1) return 0;
    const baseR = 1.6;
    if (t < 0.6) {
      const u = t / 0.6;
      const factor = Math.sin(u * Math.PI * 0.5);
      return baseR + (maxRadius - baseR) * factor;
    } else {
      const u = (t - 0.6) / 0.4;
      const factor = Math.sqrt(Math.max(0, 1 - u * u));
      return maxRadius * factor;
    }
  }

  // 1. BUILD BALLOON ENVELOPE (Teardrop Gasbag)
  for (let y = envBaseY; y <= envTopY; y++) {
    const t = (y - envBaseY) / (envH - 1);
    const r = getRadiusAtNormY(t);
    const rCeil = Math.ceil(r);

    for (let dx = -rCeil; dx <= rCeil; dx++) {
      for (let dz = -rCeil; dz <= rCeil; dz++) {
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist <= r + 0.38) {
          const vx = cx + dx;
          const vz = cz + dz;
          const isShell = dist >= r - 1.15;

          if (isShell) {
            const theta = Math.atan2(dz, dx);
            let angleNorm = (theta + Math.PI) / (2 * Math.PI);
            if (angleNorm < 0) angleNorm += 1.0;
            if (angleNorm >= 1.0) angleNorm -= 1.0;

            let block = current.primary;

            if (current.pattern === 0) {
              // 12 Vertical Gores with pinstripe seams
              const gore = (angleNorm * 12) % 12;
              const goreSub = gore % 1.0;
              const goreIdx = Math.floor(gore);
              block = (goreIdx % 2 === 0) ? current.primary : current.secondary;
              if (goreSub < 0.14 || goreSub > 0.86) block = current.accent;
              if (t >= 0.52 && t <= 0.60) block = current.trim;
            } else if (current.pattern === 1) {
              // Spiral twist
              let twist = (angleNorm + t * 1.5) % 1.0;
              if (twist < 0) twist += 1.0;
              const goreIdx = Math.floor(twist * 8);
              block = (goreIdx % 2 === 0) ? current.primary : current.secondary;
              const sub = (twist * 8) % 1.0;
              if (sub < 0.22) block = current.accent;
            } else if (current.pattern === 2) {
              // Harlequin diamonds
              const u = Math.floor(angleNorm * 12);
              const v = Math.floor(t * 8);
              block = ((u + v) % 2 === 0) ? current.primary : current.secondary;
              if (t >= 0.55 && t <= 0.62) block = current.trim;
            } else {
              // Horizontal bands with decorative equator
              const band = Math.floor(t * 7);
              if (band % 3 === 0) block = current.primary;
              else if (band % 3 === 1) block = current.secondary;
              else block = current.accent;
              if (band === 3 || band === 4) {
                const wave = Math.sin(angleNorm * 8 * Math.PI);
                if (wave > 0) block = current.trim;
              }
            }
            setSafe(vx, y, vz, block);
          } else {
            // Solid interior core ensures 6-connectivity & density
            setSafe(vx, y, vz, current.primary);
          }
        }
      }
    }
  }

  // Top Apex Valve & Victorian Spire / Pennant Flag
  setSafe(cx, envTopY + 1, cz, current.trim);
  setSafe(cx, envTopY + 2, cz, woodFence);
  setSafe(cx, envTopY + 3, cz, current.primary);
  setSafe(cx, envTopY + 3, cz - 1, current.primary);
  setSafe(cx, envTopY + 3, cz - 2, current.secondary);

  // Throat collar at the bottom of the envelope
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      if (Math.abs(dx) === 1 || Math.abs(dz) === 1) {
        setSafe(cx + dx, envBaseY, cz + dz, current.trim);
      }
    }
  }

  // 2. BURNER & HEAT CHIMNEY
  // Central heat column directly into the envelope (ensures unbroken 6-connectivity)
  for (let y = burnerY; y <= envBaseY; y++) {
    setSafe(cx, y, cz, "minecraft:glowstone");
  }
  setSafe(cx, burnerY - 1, cz, "minecraft:iron_bars");
  setSafe(cx + 1, burnerY, cz, "minecraft:iron_bars");
  setSafe(cx - 1, burnerY, cz, "minecraft:iron_bars");
  setSafe(cx, burnerY, cz + 1, "minecraft:iron_bars");
  setSafe(cx, burnerY, cz - 1, "minecraft:iron_bars");

  // Rigging lines from basket corners to throat collar
  draw6ConnectedLine(cx - 2, basketY + 2, cz - 2, cx - 1, envBaseY, cz - 1, woodFence);
  draw6ConnectedLine(cx + 2, basketY + 2, cz - 2, cx + 1, envBaseY, cz - 1, woodFence);
  draw6ConnectedLine(cx - 2, basketY + 2, cz + 2, cx - 1, envBaseY, cz + 1, woodFence);
  draw6ConnectedLine(cx + 2, basketY + 2, cz + 2, cx + 1, envBaseY, cz + 1, woodFence);

  // 3. PASSENGER BASKET (Woven Gondola)
  // Basket Floor (5x5)
  for (let x = cx - 2; x <= cx + 2; x++) {
    for (let z = cz - 2; z <= cz + 2; z++) {
      const isCorner = (Math.abs(x - cx) === 2 && Math.abs(z - cz) === 2);
      setSafe(x, basketY, z, isCorner ? woodStripped : woodPlanks);
    }
  }

  // Basket Railing / Walls (y = basketY + 1)
  for (let x = cx - 2; x <= cx + 2; x++) {
    for (let z = cz - 2; z <= cz + 2; z++) {
      const isPerimeter = (Math.abs(x - cx) === 2 || Math.abs(z - cz) === 2);
      const isCorner = (Math.abs(x - cx) === 2 && Math.abs(z - cz) === 2);
      const isNorthDoor = (x === cx && z === cz - 2 && styleIdx === 0);

      if (isCorner) {
        setSafe(x, basketY + 1, z, woodLog);
        setSafe(x, basketY + 2, z, woodFence);
      } else if (isPerimeter) {
        if (!isNorthDoor) {
          setSafe(x, basketY + 1, z, woodFence);
        }
      }
    }
  }

  // Interior basket fittings
  setSafe(cx - 1, basketY + 1, cz, woodSlab);
  setSafe(cx + 1, basketY + 1, cz, "minecraft:iron_bars");

  // Outer Ballast Sandbags on Gondola
  setSafe(cx - 3, basketY + 1, cz, current.sandbag);
  setSafe(cx + 3, basketY + 1, cz, current.sandbag);
  setSafe(cx, basketY + 1, cz + 3, current.sandbag);
  setSafe(cx - 2, basketY, cz - 2, current.sandbag);
  setSafe(cx + 2, basketY, cz - 2, current.sandbag);
  setSafe(cx - 2, basketY, cz + 2, current.sandbag);
  setSafe(cx + 2, basketY, cz + 2, current.sandbag);

  // 4. GROUND MOORING & TETHERING STATIONS
  const anchorCoords = [
    [2, 2],
    [12, 2],
    [2, 12],
    [12, 12]
  ];
  const basketCorners = [
    [cx - 2, cz - 2],
    [cx + 2, cz - 2],
    [cx - 2, cz + 2],
    [cx + 2, cz + 2]
  ];

  for (let i = 0; i < 4; i++) {
    const [ax, az] = anchorCoords[i];
    const [bx, bz] = basketCorners[i];
    const agY = groundY(ax, az);

    // Stone footing anchored into terrain
    fillColumnToGround(ax, az, agY + 1, stonePlinth);

    // Timber winch / bollard on top
    setSafe(ax, agY + 1, az, woodLog);
    setSafe(ax, agY + 2, az, "minecraft:iron_bars");

    // Sandbags around the anchor
    const offsets = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (const [ox, oz] of offsets) {
      const sx = ax + ox;
      const sz = az + oz;
      if (sx >= 0 && sx < size[0] && sz >= 0 && sz < size[2]) {
        fillColumnToGround(sx, sz, groundY(sx, sz) + 1, current.sandbag);
      }
    }

    // Heavy mooring guy-cable to basket corner
    draw6ConnectedLine(ax, agY + 2, az, bx, basketY, bz, "minecraft:chain");
  }

  // 5. INSTANCE-SPECIFIC ACCESS & CENTRAL TETHER
  if (styleIdx === 0) {
    // Boarding Gangway / Stairs on North side leading to ground
    const stairsZ = [cz - 2, cz - 3, cz - 4];
    for (let i = 0; i < stairsZ.length; i++) {
      const z = stairsZ[i];
      const targetY = basketY - i;
      fillColumnToGround(cx, z, targetY, woodPlanks);
      fillColumnToGround(cx - 1, z, targetY + 1, woodFence);
      fillColumnToGround(cx + 1, z, targetY + 1, woodFence);
    }
    // Central mooring tether straight down
    fillColumnToGround(cx, cz, basketY, woodLog);
  } else if (styleIdx === 1) {
    // Hanging rope ladder on South side down to ground
    const ladZ = cz + 2;
    fillColumnToGround(cx, ladZ, basketY, woodFence);
    fillColumnToGround(cx, cz, basketY, "minecraft:chain");
  } else if (styleIdx === 2) {
    // Grand Promenade Mooring Mast & Pylon
    fillColumnToGround(cx, cz, basketY, woodLog);
    fillColumnToGround(cx + 1, cz, basketY - 1, woodFence);
    fillColumnToGround(cx - 1, cz, basketY - 1, woodFence);
    fillColumnToGround(cx, cz + 1, basketY - 1, woodFence);
    fillColumnToGround(cx, cz - 1, basketY - 1, woodFence);
  } else {
    // Timber Launch Pad / Boardwalk Deck on ground
    const padY = seatY + 1;
    for (let x = cx - 3; x <= cx + 3; x++) {
      for (let z = cz - 3; z <= cz + 3; z++) {
        fillColumnToGround(x, z, padY, stonePavement);
      }
    }
    // Central anchor bollard
    fillColumnToGround(cx, cz, basketY, woodLog);
  }

  return {
    name: current.name,
    seatY: seatY,
    anchors: {
      front: [cx, groundY(cx, 0), 0],
      door: [cx, groundY(cx, cz - 3), cz - 3]
    }
  };
}
